pub fn parse_release(&mut self) -> Result<Statement, ParserError> {
    let _ = self.parse_keyword(Keyword::SAVEPOINT);
    let name = self.parse_identifier()?;

    Ok(Statement::ReleaseSavepoint { name })
}

